mapper.select:


    m.del_flag = '0'

        and m.stat_month = #{statMonth}


        and m.dispatch_enterprise_id = #{dispatchEnterpriseId}


        and m.person_id = #{personId}


        and m.person_name like concat('%', #{personName}, '%')


        and m.summary_status = #{summaryStatus}


        and m.att_check = #{attCheck}


        and m.region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}

order by m.stat_month desc, m.person_id asc, m.monthly_id desc

select #{statMonth} as stat_month, a.contract_id, a.contract_no, a.dispatch_enterprise_id, a.dispatch_enterprise_name, a.employer_enterprise_id, a.employer_enterprise_name, a.person_id, a.person_name, a.id_card, a.region_code, sum(case when a.attendance_status in ('1', '2', '3', '4') then 1 else 0 end) as attendance_days, sum(case when a.attendance_status = '0' then 1 else 0 end) as absence_days, sum(case when a.attendance_status = '2' then 1 else 0 end) as late_days, sum(case when a.attendance_status = '3' then 1 else 0 end) as early_leave_days, sum(ifnull(a.overtime_hours, 0)) as overtime_hours, sum(ifnull(a.attendance_hours, 0)) as total_hours, min(a.att_check) as att_check, max(a.attendance_date) as last_attendance_date from t_attendance_raw a where a.del_flag = '0' and date_format(a.attendance_date, '%Y-%m') = #{statMonth}
and a.dispatch_enterprise_id = #{dispatchEnterpriseId}
group by a.contract_id, a.contract_no, a.dispatch_enterprise_id, a.dispatch_enterprise_name, a.employer_enterprise_id, a.employer_enterprise_name, a.person_id, a.person_name, a.id_card, a.region_code

mapper.delete:
delete from t_attendance_monthly
where stat_month = #{statMonth}

    and dispatch_enterprise_id = #{dispatchEnterpriseId}
